INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.agents.delegation-validation','authority_reference',2,'docs/harness/ksdft2effmass.harness.002.001.003.md');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.agents.delegation-validation','authority_reference',3,'docs/harness/ksdft2effmass.harness.002.001.009.md');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.agents.delegation-validation','authority_reference',4,'harness/archive/task-control-v1/intake/harness.simplification.agents.delegation-validation.intake.md');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.agents.delegation-validation','authorized_scope',0,'Read the exact durable agent records, project-level disabled-agent configuration, supported runtime agent inventory, and applicable delegation procedure.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.agents.delegation-validation','authorized_scope',1,'Run at most one bounded fresh-context nonmutating capability probe for each currently selectable durable project or harness agent, using explicit prompts that grant no implementation, mutation, protected-action, or successor authority.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.agents.delegation-validation','authorized_scope',2,'Record exact runtime identities, run identifiers, terminal statuses, declared access modes and skills, malformed or unavailable results, and any mismatch between durable records, discovery configuration, and runtime delegation behavior.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.agents.delegation-validation','authorized_scope',3,'Produce one compact project-local software-verification report and obtain one consolidated independent read-only review of the report and its declared runtime evidence.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.agents.delegation-validation','completion_criterion',0,'The selectable durable-agent inventory and disabled historical-agent inventory agree with the exact maintained records and project configuration, with every discrepancy reported rather than normalized away.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.agents.delegation-validation','completion_criterion',1,'Every selectable durable agent has exactly one retained bounded probe disposition, and no disabled historical agent is launched merely to demonstrate that it is disabled.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.agents.delegation-validation','completion_criterion',2,'Probe results establish only discovery and delegation transport behavior; they do not claim agent correctness, Task authorization, scientific validity, protected-action authority, or human acceptance.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.agents.delegation-validation','completion_criterion',3,'The independent review has no unresolved material finding, focused structural checks pass, unrelated repository state is preserved, and no dependency or lockfile changes occur.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.agents.delegation-validation','completion_criterion',4,'On completion the Task becomes completed, chain active_task returns to null, automatic successor activation remains false, and no successor is activated.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.agents.delegation-validation','exclusion',0,'Do not edit durable or historical agent records, revive or delete historical agents, change project discovery configuration, add another dispatcher or replay layer, or redesign the delegation runtime.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.agents.delegation-validation','exclusion',1,'Do not assign production implementation, documentation mutation, test mutation, scientific work, external execution, release work, or another Task through a capability probe.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.agents.delegation-validation','exclusion',2,'Do not add dependencies, change lockfiles, implement SQLite or evidence persistence, reopen H0-H4, or activate review-dispatch-idempotency, evidence-and-sqlite, scientific, publication, release, or protected work.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.api.action-object-grammar','authority_reference',0,'.pi/chains/harness-simplification.chain.json');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.api.action-object-grammar','authority_reference',1,'harness/archive/task-control-v1/tasks/harness.simplification.api.action-object-grammar.md');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.api.action-object-grammar','authorized_scope',0,'Establish and migrate the repository-wide public ActionObject naming grammar:');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.api.action-object-grammar','authorized_scope',1,'Human decision: this is pre-release software with no public API consumers requiring compatibility preservation. Apply hard renames with no compatibility aliases or deprecation period. Preserve already conforming suffix-style names and migrate only the accepted nonconforming inventory. Use old/new mappings only where an owning maintained-evidence contract requires node-identity migration; do not create API-compatibility ceremony. Synchronize source, tests, documentation, skills, wrappers, schemas, fixtures, manifests, and public exports. The evidence-subpackage API must follow the accepted grammar.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.api.action-object-grammar','completion_criterion',0,'Completion requires the accepted convention in every owning surface, complete affected-object inventory, deterministic naming checks, only contract-required maintained-evidence node mappings, synchronized public surfaces, relevant tests and documentation checks, one consolidated review, and final human acceptance when required.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.api.action-object-grammar','exclusion',0,'Human decision: this is pre-release software with no public API consumers requiring compatibility preservation. Apply hard renames with no compatibility aliases or deprecation period. Preserve already conforming suffix-style names and migrate only the accepted nonconforming inventory. Use old/new mappings only where an owning maintained-evidence contract requires node-identity migration; do not create API-compatibility ceremony. Synchronize source, tests, documentation, skills, wrappers, schemas, fixtures, manifests, and public exports. The evidence-subpackage API must follow the accepted grammar.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.api.action-object-grammar','exclusion',1,'This Task does not change DataObject ownership, operation behavior, scientific meaning, wire formats, dependencies, or runtime policy merely to obtain naming consistency.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.api.action-object-grammar','exclusion',2,'This Task does not authorize unrelated API redesign, add dependencies, introduce SQLite, perform protected execution, or activate successors.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.control.successor-selection','authority_reference',0,'.pi/chains/harness-simplification.chain.json');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.control.successor-selection','authority_reference',1,'harness/archive/task-control-v1/intake/harness.simplification.control.successor-selection.intake.md');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.control.successor-selection','authorized_scope',0,'Inspect bounded durable chain and exact Task records to identify prerequisite-eligible inactive harness-simplification candidates.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.control.successor-selection','authorized_scope',1,'Present the eligible choices and their controlling scope, prerequisites, protected boundaries, and unresolved decisions to the human authority.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.control.successor-selection','authorized_scope',2,'After one unambiguous current human selection, update the selected Task and chain activation facts through the applicable durable procedure.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.control.successor-selection','completion_criterion',0,'No candidate is presented as active or authorized merely because it is eligible, ordered next, documented, or recommended.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.control.successor-selection','completion_criterion',1,'Exactly one unambiguous current human selection is preserved in durable control state before activation.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.control.successor-selection','completion_criterion',2,'The chain active_task, selected Task status, and explicit activation facts agree, automatic successor activation remains false, and focused state inspection passes.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.control.successor-selection','exclusion',0,'Do not select a successor on behalf of the human, infer approval from silence or prior completion, or activate more than one Task.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.control.successor-selection','exclusion',1,'Do not expand the selected Task scope, execute its implementation, perform protected work, or treat a reviewer or deterministic check as human acceptance.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.control.successor-selection','exclusion',2,'Do not activate this Task automatically; a later current human instruction must authorize its activation after prerequisites are satisfied.');
