INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.control.task-catalog-reconciliation','authority_reference',3,'docs/harness/ksdft2effmass.harness.002.001.009.md');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.control.task-catalog-reconciliation','authority_reference',4,'harness/archive/task-control-v1/intake/harness.simplification.control.task-catalog-reconciliation.intake.md');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.control.task-catalog-reconciliation','authorized_scope',0,'Inspect the exact harness-simplification chain, its declared Task records, and maintained current or prospective harness pages that enumerate proposed, completed, deferred, rejected, or out-of-scope work.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.control.task-catalog-reconciliation','authorized_scope',1,'Create one deterministic project-local catalog in which each distinct documented work item has exactly one disposition: EXISTING_TASK, COMPLETED_BY, TASK_RECORD_REQUIRED, DEFERRED, REJECTED, or OUTSIDE_HARNESS_SCOPE.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.control.task-catalog-reconciliation','authorized_scope',2,'Record exact source references, current chain identity when present, prerequisite evidence, protected or human-owned boundaries, naming inconsistencies, duplicate concepts, and the reason for each disposition.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.control.task-catalog-reconciliation','authorized_scope',3,'Reconcile chain membership and explicit inactive dispositions only where the catalog deterministically demonstrates a missing or duplicate control entry; do not create executable successor contracts merely to populate the list.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.control.task-catalog-reconciliation','authorized_scope',4,'Obtain one consolidated independent read-only review of catalog completeness, disposition consistency, authority boundaries, chain reconciliation, and nonactivation.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.control.task-catalog-reconciliation','completion_criterion',0,'Every distinct item in the declared source pages and every chain entry appears exactly once in the catalog or has an explicit duplicate-of relation to its owning item.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.control.task-catalog-reconciliation','completion_criterion',1,'Every catalog entry has exactly one allowed disposition, exact source references, and an identified existing owner, completion owner, missing-record boundary, deferral authority, rejection authority, or scope boundary as applicable.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.control.task-catalog-reconciliation','completion_criterion',2,'The chain and catalog agree on identities, records, prerequisites, completed conceptual entries, inactive proposals, superseded entries, and any deterministically added inactive disposition entries.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.control.task-catalog-reconciliation','completion_criterion',3,'Legacy hyphenated and normalized dot-separated identities are reported without renaming completed or historical identities; any future identity migration requiring human choice remains unresolved rather than silently normalized.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.control.task-catalog-reconciliation','completion_criterion',4,'Focused schema, catalog, chain, projection, checkpoint, documentation, dependency-scope, and whitespace checks pass, and the independent review has no unresolved material finding.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.control.task-catalog-reconciliation','completion_criterion',5,'On completion this Task becomes completed, chain active_task returns to null, automatic successor activation remains false, and no implementation successor is activated.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.control.task-catalog-reconciliation','exclusion',0,'Do not implement SQLite, persistence, migrations, event logs, execution records, package extraction, adapter removal, telemetry, publication, release, scientific work, external execution, or destructive retirement.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.control.task-catalog-reconciliation','exclusion',1,'Do not create, activate, prioritize, or assign an implementation Task solely because a proposal is documented or cataloged; TASK_RECORD_REQUIRED records a missing boundary rather than authorizing a new Task.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.control.task-catalog-reconciliation','exclusion',2,'Do not rewrite accepted historical Task identities, retained evidence, checkpoints, agent records, or completed decision records, and do not treat the catalog or documentation as human acceptance.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.control.task-catalog-reconciliation','exclusion',3,'Do not add dependencies, change lockfiles, perform Graphify, launch protected work, or activate review-dispatch-idempotency, evidence-and-sqlite, P3, publication, release, or any automatic successor.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json','authority_reference',0,'.pi/chains/harness-simplification.chain.json');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json','authority_reference',1,'docs');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json','authority_reference',2,'harness/archive/task-control-v1/tasks/harness.simplification.docs-json.md');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json','authorized_scope',0,'Correct the synchronization and authority delta between human-readable `docs/`, transitional Task records, and the selected JSON control surface. Preserve human-authored intake and documentation-owned subject matter while moving operational control fields to JSON-backed generated reference pages.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json','completion_criterion',0,'The parent is complete when each decomposed Task completes, their inputs and outputs agree, deterministic corrections are applied, unresolved findings have explicit dispositions, and one consolidated parent integration review passes. No extra parent acceptance step is required unless a material human-owned choice remains.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json','exclusion',0,'Markdown Task records are transitional and non-executable. Before the JSON Task contract exists, only a current explicit human instruction may activate one exact Task. No child activates automatically, parent completion is not computed, scope is not inferred from the identifier hierarchy, and chain evaluation does not interpret Markdown decomposition.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json','exclusion',1,'Generic harness code may own neutral explicit-input inventory, hashing, extraction-result, relationship, partition-validation, schema-validation, and rendering mechanics. Project-local code owns repository roots, authority policy, document roles, Task identities, control schemas, projection profiles, and human decisions. Generic code must not depend on `.pi/` or ksdft2effmass-specific identities.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.authority-catalog','authority_reference',0,'.pi/chains/harness-simplification.chain.json');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.authority-catalog','authority_reference',1,'docs');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.authority-catalog','authority_reference',2,'harness/archive/task-control-v1/tasks/harness.simplification.docs-json.authority-catalog.md');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.authority-catalog','authorized_scope',0,'After publication hierarchy normalization, compare human-readable material under `docs/` with the selected JSON control surface and explicitly selected transitional control records. Apply repository precedence to identify deterministic documentation corrections and isolate only genuinely unresolved authority questions.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.authority-catalog','authorized_scope',1,'docs-initial.json');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.authority-catalog','authorized_scope',2,'control-initial.json');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.authority-catalog','authorized_scope',3,'authority-mappings.json');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.authority-catalog','authorized_scope',4,'docs-residual.json');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.authority-catalog','authorized_scope',5,'control-residual.json');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.authority-catalog','authorized_scope',6,'catalog-manifest.json');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.authority-catalog','completion_criterion',0,'Completion requires complete path coverage for the declared roots and revision, valid JSON, reproducible identities and counts, explicit treatment of parse failures, a verified whole-file/residual partition, and bounded semantic claims.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.authority-catalog','completion_criterion',1,'The baseline may claim complete path coverage only for its declared inputs. It must not claim complete semantic extraction or repository-wide authority analysis. It does not modify represented files, resolve scientific meaning, or introduce SQLite.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.authority-catalog','exclusion',0,'The catalog set is a temporary migration aid, not authority, a runtime registry, or permanent architecture.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.authority-catalog','exclusion',1,'It does not modify represented files, resolve scientific meaning, or introduce SQLite.');
