INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.documentation-correction','authority_reference',1,'.pi/evidence/docs-json/authority-catalog/authority-mappings.json');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.documentation-correction','authorized_scope',0,'Apply deterministic corrections directly, including stale status, activation, prerequisite, successor, completion, or acceptance prose whose operational owner is a chain or Task record; obsolete names and links; manual restatements that will be replaced by generated control-reference pages; historical material that is not clearly labeled historical; and naming that violates an accepted convention.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.documentation-correction','authorized_scope',1,'Resolve only the remaining ambiguity queue, asking the human only when applicable claims conflict, precedence does not resolve them, and materially different defensible corrections remain.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.documentation-correction','authorized_scope',2,'Validate links, names, historical/current labeling, and the absence of documentation-only activation paths.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.documentation-correction','authorized_scope',3,'Hand the remaining operational record families to harness.simplification.docs-json.schema-projection.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.documentation-correction','authorized_scope',4,'Documentation may locate or explain work, but it cannot activate a Task or supply executable scope; do not invent a new execution-target resolver unless an actual executable path violates this rule and a separate Task authorizes that behavior.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.documentation-correction','completion_criterion',0,'Corrected documentation and resolved links preserve subject-matter contracts and human intake, record an explicit unresolved list if any, and provide a bounded schema-projection handoff.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.documentation-correction','exclusion',0,'Do not create a human checkpoint for a deterministic correction governed by accepted authority.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.documentation-correction','exclusion',1,'Do not change scientific meaning, activate work, resolve checkpoints, create runtime routing, or perform repository-wide rewriting beyond authorized paths.');
