INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.publication','authorized_scope',0,'Triage publication-preparation files and apply one coherent hierarchy before documentation/control-surface comparison.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.publication','completion_criterion',0,'This parent is complete when both Tasks complete, their input/output identities agree, and unresolved publication roles have an explicit disposition. It does not add a separate parent acceptance step unless a material human-owned choice remains.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.publication','exclusion',0,'This parent is complete when both Tasks complete, their input/output identities agree, and unresolved publication roles have an explicit disposition. It does not add a separate parent acceptance step unless a material human-owned choice remains.');
