INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.publication.hierarchy','authorized_scope',0,'Use the accepted triage from `harness.simplification.docs-json.publication.triage` to place publication working source, submission snapshots, generated output, external material, provenance, historical artifacts, and direct project documentation in a coherent hierarchy without changing their content or meaning.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.publication.hierarchy','authorized_scope',1,'The human PI explicitly authorized deletion of only `docs/conferences/ICMSEP2026/LA2.pdf`, movement of the two publication trees under `docs/publications/`, and creation of `docs/publications/ksdft2effmass.publications.00.md` from the empty tracked conference file.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.publication.hierarchy','completion_criterion',0,'Completion requires the applied path map, resolved links, correct generated/external/source treatment, preserved content identities, and a compact handoff to `harness.simplification.docs-json.authority-catalog`.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.publication.hierarchy','completion_criterion',1,'This Task does not alter scientific or publication claims, publish, submit, or release material. The human PI explicitly authorized deletion of only `docs/conferences/ICMSEP2026/LA2.pdf`, movement of the two publication trees under `docs/publications/`, and creation of `docs/publications/ksdft2effmass.publications.00.md` from the empty tracked conference file. No other deletion is authorized.');
