INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.task-document-migration','completion_criterion',2,'Every packet contains all eight required before/after elements and clearly distinguishes explained mapped transformations from exact unexplained differences and human acceptance.');
