INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.task-model-contract','authorized_scope',2,'Classify every selected source span as canonical Task information, documentation-owned narrative or opaque content, historical evidence, or an explicitly proposed removal requiring human decision; preserve exact source identities and bytes.');
