INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.task-model-contract','authorized_scope',4,'Define explicit renderer inputs as HarnessTask plus explicit HarnessTaskDocumentationContent plus HarnessTaskProjectionProfile, with no implicit filesystem, current-working-directory, repository-root, global-template, or parser-state input.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.task-model-contract','authorized_scope',5,'Complete the proposed information model and diagrams for canonical Task information, exact source identity and bytes, source-span mappings, documentation-owned and opaque content, projection configuration, rendered output, exact comparison, structured findings and unmapped spans, explicit packet-preparation input, immutable per-file migration review packets, exact human file dispositions, and mixed Markdown/JSON compatibility ownership.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.task-model-contract','authorized_scope',6,'Define HarnessTaskMigrationReviewPacketRequest as an immutable runtime-only DataObject containing the exact source, complete ordered mappings, candidate Task, canonical serialized Task JSON bytes, documentation content, projection profile, rendered documentation, comparison result, and composed HumanReviewPacket; assign only intrinsic type, immutability, tuple, nonempty, and lexical invariants to its constructor unless a separately justified wire requirement is accepted.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.task-model-contract','authorized_scope',7,'Define HarnessTaskMigrationReviewPacketPreparer as a stateless ActionObject with execute(request: HarnessTaskMigrationReviewPacketRequest) -> HarnessTaskMigrationReviewPacket; assign all cross-object identity, complete ordered nonoverlapping coverage, source-reference, Task/JSON, documentation/span, profile/rendering, comparison, generic-review target/revision, and deterministic packet-construction validation to the preparer without duplicating generic HumanReviewPreparer semantics.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.task-model-contract','authorized_scope',8,'Preserve HarnessTaskMigrationReviewPacket as the immutable preparer result, HumanReviewDecisionRecorder as owner of the generic human decision, and HarnessTaskMigrationFileDispositionRecorder as the migration-domain action validating the exact packet/decision relationship; none may interpret human authority.');
