INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.task-model-contract','completion_criterion',2,'The maintained proposal accounts for exactly 19 proposed interfaces and exactly 20 Mermaid class diagrams, including one focused diagram for every proposed interface, while reused classes remain excluded from the proposed-interface count.');
