INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplify-2.cli-consolidation','completion_criterion',3,'All maintained command references use `python/.venv/bin/python python/src/cli/<command>.py`; generated shell and inline-Python command fragments are absent from live routing.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplify-2.cli-consolidation','completion_criterion',4,'One maintained synchronization command delegates complete database construction and publication to `HarnessControlMigrator`, and one maintained check surface reports deterministic control agreement; exact user-facing spellings are selected during implementation without creating another persistence owner.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplify-2.cli-consolidation','completion_criterion',5,'Historical `.pi` evidence, exact prior command records, and historical scripts remain unchanged and are not treated as maintained live CLI implementations.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplify-2.cli-consolidation','completion_criterion',6,'Focused CLI and command/API agreement tests establish explicit arguments, full-migration delegation, output, exit status, nonmutation or authorized-publication boundaries, documentation and resource agreement, and dependency-lock nonmutation.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplify-2.cli-consolidation','exclusion',0,'Do not move reusable ActionObject, DataObject, ResultObject, validation, persistence, parsing, serialization, or scientific behavior into `python/src/cli/`; CLI scripts remain thin adapters and renderers.');
